import React from "react";
import AccelLogo from "assets/img/accel_logo.png";

export default function Footer() {
  return (
    <footer className="bg-[#1c2340] text-white">
      {/* Bloc 3 colonnes */}
      <div className="max-w-[1200px] mx-auto px-6 lg:px-10 py-16 lg:py-20 grid grid-cols-1 md:grid-cols-3 gap-14">
        {/* Colonne 1 : Powered By */}
        <div className="flex flex-col items-start md:items-start">
          <h3 className="font-semibold leading-none text-4xl sm:text-5xl mb-8">
            Powered By
          </h3>

          <img
            src={AccelLogo}
            alt="Accel"
            className="h-24 w-auto select-none"
          />
        </div>

        {/* Colonne 2 : Liens utiles */}
        <div>
          <h3 className="font-semibold leading-none text-4xl sm:text-5xl mb-8">
            Liens utiles
          </h3>

          <ul className="space-y-6">
            <li className="flex items-center gap-4">
              <i className="fas fa-link text-2xl opacity-90" />
              <a
                href="#"
                className="text-2xl sm:text-3xl tracking-wide hover:underline"
              >
                Red Hat Enterprise Linux
              </a>
            </li>
            <li className="flex items-center gap-4">
              <i className="fas fa-link text-2xl opacity-90" />
              <a
                href="#"
                className="text-2xl sm:text-3xl tracking-wide hover:underline"
              >
                Openshift AI
              </a>
            </li>
            <li className="flex items-center gap-4">
              <i className="fas fa-link text-2xl opacity-90" />
              <a
                href="#"
                className="text-2xl sm:text-3xl tracking-wide hover:underline"
              >
                Heritage Cloud
              </a>
            </li>
          </ul>
        </div>

